const fs = require('fs');
const path = require('path');

// Error subclass updates: file -> errorCode
const subclasses = {
  'packages/payload/src/errors/Forbidden.ts': { code: 'FORBIDDEN', pattern: /super\(\n(\s+)t \? t/, replacement: 'super(\n\$1\\'FORBIDDEN\\',\n\$1t ? t' },
  'packages/payload/src/errors/NotFound.ts': { code: 'NOT_FOUND', pattern: /super\(t \? t/, replacement: 'super(\\'NOT_FOUND\\', t ? t' },
  'packages/payload/src/errors/AuthenticationError.ts': { code: 'AUTHENTICATION_ERROR', pattern: /super\(\n(\s+)t\n/, replacement: 'super(\n\$1\\'AUTHENTICATION_ERROR\\',\n\$1t\n' },
  'packages/payload/src/errors/Locked.ts': { code: 'LOCKED', pattern: /super\(message, httpStatus\.LOCKED\)/, replacement: 'super(\\'LOCKED\\', message, httpStatus.LOCKED)' },
  'packages/payload/src/errors/LockedAuth.ts': { code: 'LOCKED_AUTH', pattern: /super\(t \? t\('error:userLocked'\)/, replacement: 'super(\\'LOCKED_AUTH\\', t ? t(\\'error:userLocked\\')' },
  'packages/payload/src/errors/UnauthorizedError.ts': { code: 'UNAUTHORIZED', pattern: /super\(t \? t\('error:unauthorized'\)/, replacement: 'super(\\'UNAUTHORIZED\\', t ? t(\\'error:unauthorized\\')' },
};

// Simple approach: just read each file, find the super( call and insert errorCode
const files = {
  'packages/payload/src/errors/Forbidden.ts': 'FORBIDDEN',
  'packages/payload/src/errors/NotFound.ts': 'NOT_FOUND',
  'packages/payload/src/errors/AuthenticationError.ts': 'AUTHENTICATION_ERROR',
  'packages/payload/src/errors/ValidationError.ts': 'VALIDATION_ERROR',
  'packages/payload/src/errors/Locked.ts': 'LOCKED',
  'packages/payload/src/errors/LockedAuth.ts': 'LOCKED_AUTH',
  'packages/payload/src/errors/UnauthorizedError.ts': 'UNAUTHORIZED',
  'packages/payload/src/errors/UnverifiedEmail.ts': 'UNVERIFIED_EMAIL',
  'packages/payload/src/errors/QueryError.ts': 'QUERY_ERROR',
  'packages/payload/src/errors/InvalidConfiguration.ts': 'INVALID_CONFIGURATION',
  'packages/payload/src/errors/FileRetrievalError.ts': 'FILE_RETRIEVAL_ERROR',
  'packages/payload/src/errors/TimestampsRequired.ts': 'TIMESTAMPS_REQUIRED',
  'packages/payload/src/errors/InvalidFieldJoin.ts': 'INVALID_FIELD_JOIN',
  'packages/payload/src/errors/MissingFieldInputOptions.ts': 'MISSING_FIELD_INPUT_OPTIONS',
  'packages/payload/src/errors/ErrorDeletingFile.ts': 'ERROR_DELETING_FILE',
  'packages/payload/src/errors/MissingCollectionLabel.ts': 'MISSING_COLLECTION_LABEL',
  'packages/payload/src/errors/DuplicateFieldName.ts': 'DUPLICATE_FIELD_NAME',
  'packages/payload/src/errors/FileUploadError.ts': 'FILE_UPLOAD_ERROR',
  'packages/payload/src/errors/InvalidFieldName.ts': 'INVALID_FIELD_NAME',
  'packages/payload/src/errors/DuplicateCollection.ts': 'DUPLICATE_COLLECTION',
  'packages/payload/src/errors/MissingFieldType.ts': 'MISSING_FIELD_TYPE',
  'packages/payload/src/errors/InvalidFieldRelationship.ts': 'INVALID_FIELD_RELATIONSHIP',
  'packages/payload/src/errors/MissingEditorProp.ts': 'MISSING_EDITOR_PROP',
};

for (const [file, code] of Object.entries(files)) {
  let content = fs.readFileSync(file, 'utf8');
  // Find 'super(' inside the constructor and add errorCode as first arg
  // Pattern: find 'super(' followed by newline+indent or directly by first arg
  // We need to insert the errorCode after 'super('

  // Handle multiline super calls: super(\n      arg
  content = content.replace(/super\(\n(\s+)/, (match, indent) => {
    return 'super(\n' + indent + \"'\" + code + \"',\n\" + indent;
  });

  // Handle single-line super calls: super(arg  
  // But only if we didn't already modify it (check if code is already there)
  if (!content.includes(\"'\" + code + \"'\")) {
    content = content.replace(/super\(([^)])/,  (match, firstChar) => {
      return \"super('\" + code + \"', \" + firstChar;
    });
  }

  fs.writeFileSync(file, content);
  console.log('Updated: ' + file);
}

console.log('Done with subclasses');
"

