function getErrorCode(msg, status) {
  const m = (msg || '').toLowerCase();

  // Status-based codes
  if (status === 401 || status === '401' || status === 'httpStatus.UNAUTHORIZED') return 'UNAUTHORIZED';
  if (status === 403 || status === '403' || status === 'httpStatus.FORBIDDEN') return 'FORBIDDEN';
  if (status === 404 || status === '404' || status === 'httpStatus.NOT_FOUND') return 'NOT_FOUND';
  if (status === 413 || status === '413' || status === 'httpStatus.REQUEST_ENTITY_TOO_LARGE') return 'REQUEST_TOO_LARGE';
  if (status === 418 || status === '418') return 'BAD_REQUEST';
  if (status === 422 || status === '422') return 'UNPROCESSABLE_ENTITY';
  if (status === 423 || status === '423') return 'LOCKED';
  if (status === 429 || status === '429') return 'TOO_MANY_REQUESTS';

  // Message-based refinements for 400-level
  if (status === 400 || status === '400' || status === 'httpStatus.BAD_REQUEST') {
    if (m.includes('missing')) return 'BAD_REQUEST';
    if (m.includes('invalid')) return 'BAD_REQUEST';
    if (m.includes('upload') || m.includes('file')) return 'BAD_REQUEST';
    return 'BAD_REQUEST';
  }

  // Default / 500
  if (m.includes('not found')) return 'NOT_FOUND';
  if (m.includes('not supported')) return 'INTERNAL_ERROR';
  return 'INTERNAL_ERROR';
}

