function getErrorCode(msg, status) {
  const m = (msg || '').toLowerCase();
  if (status === 401) return 'UNAUTHORIZED';
  if (status === 403) return 'FORBIDDEN';
  if (status === 404) return 'NOT_FOUND';
  if (status === 413) return 'REQUEST_TOO_LARGE';
  if (status === 418) return 'BAD_REQUEST';
  if (status === 422) return 'UNPROCESSABLE_ENTITY';
  if (status === 423) return 'LOCKED';
  if (status === 429) return 'TOO_MANY_REQUESTS';
  if (status === 400) return 'BAD_REQUEST';
  if (m.includes('not found')) return 'NOT_FOUND';
  if (m.includes('not supported')) return 'INTERNAL_ERROR';
  return 'INTERNAL_ERROR';
}

function parseStatus(s) {
  if (!s) return 500;
  const map = {
    'httpStatus.BAD_REQUEST': 400,
    'httpStatus.UNAUTHORIZED': 401,
    'httpStatus.FORBIDDEN': 403,
    'httpStatus.NOT_FOUND': 404,
    'httpStatus.REQUEST_ENTITY_TOO_LARGE': 413,
    'httpStatus.INTERNAL_SERVER_ERROR': 500,
    'httpStatus.LOCKED': 423,
  };
  if (map[s]) return map[s];
  const n = parseInt(s);
  return isNaN(n) ? 500 : n;
}

let totalUpdated = 0;

for (const file of files) {
  if (!fs.existsSync(file)) {
    console.log('SKIP (not found): ' + file);
    continue;
  }

  let content = fs.readFileSync(file, 'utf8');
  const lines = content.split('\n');
  let modified = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const idx = line.indexOf('new APIError(');
    if (idx === -1) continue;

    const afterParen = line.substring(idx + 'new APIError('.length);

    // Check if rest of args is on this line or next line
    if (afterParen.trim() === '' || afterParen.trim() === ')') {
      // Multiline: args start on next line
      // Find the first non-empty line after this
      let nextLineIdx = i + 1;
      while (nextLineIdx < lines.length && lines[nextLineIdx].trim() === '') nextLineIdx++;

      if (nextLineIdx < lines.length) {
        const nextLine = lines[nextLineIdx];
        const indent = nextLine.match(/^(\s*)/)[1];

        // Extract msg and status from the multiline call
        // Collect all lines until closing paren to find status
        let argText = '';
        for (let j = nextLineIdx; j < Math.min(nextLineIdx + 10, lines.length); j++) {
          argText += lines[j] + '\n';
          if (lines[j].includes(')') && !lines[j].includes('(')) break;
          // Also stop if the line has a closing paren that matches
        }

        // Try to get first arg (string) and second arg (status)
        let msg = '';
        let status = 500;

        // Match string literal
        const strMatch = argText.match(/['"`]([^'"`]*?)['"`]/);
        if (strMatch) msg = strMatch[1];

        // Match status
        const statusMatch = argText.match(/,\s*(\d+|httpStatus\.\w+)/);
        if (statusMatch) status = parseStatus(statusMatch[1]);

        const errorCode = getErrorCode(msg, status);

        // Insert error code line before the first arg line
        lines.splice(nextLineIdx, 0, indent + "'" + errorCode + "',");
        i++; // skip the inserted line
        modified = true;
        totalUpdated++;
      }
    } else {
      // Single line or args start on same line
      // Insert errorCode after 'new APIError('
      const prefix = line.substring(0, idx + 'new APIError('.length);
      const rest = line.substring(idx + 'new APIError('.length);

      // Extract msg and status
      let msg = '';
      let status = 500;

      const strMatch = rest.match(/^['"`]([^'"`]*?)['"`]/);
      const tmplMatch = rest.match(/^`([^`]*?)`/);
      if (strMatch) msg = strMatch[1];
      else if (tmplMatch) msg = tmplMatch[1];

      const statusMatch = rest.match(/,\s*(\d+|httpStatus\.\w+)/);
      if (statusMatch) status = parseStatus(statusMatch[1]);

      // Also check for variable first arg
      if (!strMatch && !tmplMatch) {
        const varMatch = rest.match(/^(\w[\w.]*!?)\s*,\s*(\d+|httpStatus\.\w+)/);
        if (varMatch) {
          msg = varMatch[1];
          status = parseStatus(varMatch[2]);
        } else {
          const varOnly = rest.match(/^(\w[\w.]*!?)\s*[,)]/);
          if (varOnly) msg = varOnly[1];
        }
      }

      const errorCode = getErrorCode(msg, status);

      lines[i] = prefix + "'" + errorCode + "', " + rest;
      modified = true;
      totalUpdated++;
    }
  }

  if (modified) {
    content = lines.join('\n');
    fs.writeFileSync(file, content);
    console.log('Updated: ' + file + ' (' + (lines.filter(l => l.includes("new APIError('" + '')).length) + ' sites)');
  }
}

console.log('\nTotal call sites updated: ' + totalUpdated);
